with d as (select value r from jsonb_array_elements($q$[{"notes":["Best served warm with crusty bread to soak up the sauce.","Keeps well in the fridge for 3 days. Reheat gently on the stove, adding a splash of water if it's too thick."],"id":"20e3e39f-f2cb-4228-92f5-afb84cfdda6d"},{"notes":["The toasted rice powder is the heart of this dish, make it fresh each time you cook. It won't keep.","Naam tok is best eaten warm, but it's fine at room temperature too. Leftovers don't hold up overnight.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Toast the jasmine rice in a dry frying pan over medium heat, shaking often, until it turns golden and smells nutty, about 3–4 minutes. Let it cool, then pound it in a mortar until it's crumbly with some fine powder, not flour-fine, but grainy."},{"text":"Pat the chicken dry and brush lightly with oil. Heat a chargrill or barbecue to high, then grill the chicken, turning once, until cooked through (75°C inside), about 8–10 minutes. Let it rest for 2 minutes, then slice into bite-sized pieces."},{"text":"Whisk the lime juice, fish sauce and sugar together in a small bowl until the sugar dissolves."},{"text":"Put the warm chicken in a large bowl with the dressing and toss well. Add the toasted rice powder, green chilli, coriander, mint and spring onions, and toss again."},{"text":"Taste and add salt or a squeeze more lime juice if you need it. Serve warm or at room temperature."}],"id":"d0926cdd-dc86-48e4-bdc7-26e1415e81dc"},{"steps":[{"text":"Make the vinegar dip: combine vinegar, garlic, chilli and a pinch of salt in a small bowl. Let it sit for 5 minutes so the flavours come together."},{"text":"Pat the grouper dry inside and out. Make three shallow scores across each side of the fish – this helps it cook through and caramelises the skin. Brush lightly with oil and season generously with salt and pepper, inside the cavity and on both sides."},{"text":"Heat a large char-grill or grill plate to high until very hot and smoking lightly. Oil the grates well."},{"text":"Place the grouper on the grill and cook without moving it for 8–10 minutes, until the skin is charred and crisp and releases easily from the grate. Flip carefully and cook the other side for 8–10 minutes, until the flesh near the backbone is opaque and cooked through (check by inserting a knife at the thickest point)."},{"text":"Transfer to a warm plate, squeeze lime over it and serve at the table with the vinegar dip on the side for each person to help themselves."}],"id":"d2f01041-f415-4eeb-a31e-85b1053440c4"},{"notes":["Mash or mashed potato on the side soaks up the gravy beautifully.","Use a good butcher's sausage, it makes all the difference.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"steps":[{"text":"Heat oil in a large heavy pan or cast-iron frying pan over medium-high heat. Brown the sausages all over until golden, about 8 minutes. Set aside."},{"text":"In the same pan, add the sliced onions and reduce heat to medium-low. Cook, stirring occasionally, until the onions are soft and deep golden brown, about 20 minutes. Be patient, this is where the flavour comes from."},{"text":"Stir in the tomato paste and cook for 1 minute, then add the beef stock and worcestershire sauce. Return the sausages to the pan."},{"text":"Simmer gently for 15 minutes until the sausages are cooked through and the gravy has thickened slightly. Season with salt and pepper to taste."},{"text":"Serve the snags on a plate with the onion gravy spooned over."}],"id":"9469225d-5b84-4129-b1b3-7b7772d62fd4"},{"notes":["Store in an airtight container at room temperature for up to 3 days, or refrigerate for up to a week.","This cake is best made a day ahead, the flavour deepens and the texture becomes even better.","Don't skip squeezing out the moisture from the cassava; it makes all the difference to how the cake sets."],"steps":[{"text":"Preheat the oven to 180°C. Line a 20 cm × 30 cm baking tin with baking paper."},{"text":"Squeeze the grated cassava firmly over a bowl to remove excess moisture, this is important for the right texture. Transfer to a large bowl."},{"text":"Add the coconut milk, caster sugar, vanilla extract and salt. Stir well until the sugar is dissolved and everything is combined."},{"text":"Pour into the prepared tin, spreading evenly."},{"text":"Bake for 45–50 minutes, until the top is golden and a skewer inserted into the centre comes out clean."},{"text":"Cool in the tin for 10 minutes, then turn out onto a wire rack to cool completely. Cut into squares to serve."}],"id":"d88687aa-be33-4a63-83b4-56e21906c6ae"},{"notes":["Barramundi is best when fresh and cooked simply. If you can't find barramundi, use any firm white fish fillet like snapper or bream.","Serve with steamed jasmine rice and a quick salad of cucumber and lime to cut through the richness.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"3417bb88-3a85-4d31-bbb4-5fa001f2397f"},{"notes":["Use bone-in chicken thighs if you can find them, they add more flavour to the broth as everything cooks.","This keeps well in the fridge for up to 3 days and reheats gently on the stove with a splash of water.","Cook mince and sausages until they reach 75°C in the centre, with no pink left.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone. Cook mince, sausages, meatballs and liver right through to 75°C, with no pink in the centre."],"id":"d8664841-c7b9-435b-a4e2-ea48eadbc9a4"},{"notes":["Make ahead: prepare the dashi dressing the night before and keep chilled.","The spinach must be cooled completely before dressing, or the dashi will warm and lose its clean taste.","Serve in shallow bowls if you have them, obanzai looks best on good ceramics."],"steps":[{"text":"Bring a large pot of salted water to a boil. Cook the spinach, stirring gently, until tender and wilted, about 2 minutes. Drain in a colander."},{"text":"Gather the spinach into a ball and gently squeeze out excess water with your hands. Do this carefully, the leaves should stay tender. Set aside to cool."},{"text":"Combine the dashi, soy sauce and mirin in a bowl. Chill in the refrigerator until cold."},{"text":"Once the spinach has cooled, cut it into 4 cm lengths and arrange in a serving bowl or on a plate."},{"text":"Pour the cold dashi dressing over the spinach just before serving, or let each person pour their own at the table. Top with bonito flakes."},{"text":"Serve immediately, chilled."}],"id":"1c32ea24-70e8-45a6-bda7-afbfb67ededb"},{"steps":[{"text":"Make the paste: whisk glutinous rice flour, water and sugar in a saucepan. Bring to a simmer over medium heat, stirring constantly, until thickened and translucent, about 3 minutes. Remove from heat and stir in the garlic, ginger, gochugaru and fish sauce. Set aside to cool slightly."},{"text":"Prepare the gat: cut the stems into 5 cm lengths. Leave the leaves whole or tear into 10 cm pieces if very large. Rinse well under cold water."},{"text":"Salt the gat: layer the stems and leaves in a large bowl, sprinkling 2 tbsp of salt evenly as you go. Let sit for 15 minutes, then massage gently with your hands, turning the leaves over to coat all sides. The gat will soften and release liquid, this is correct. Drain off most of the liquid."},{"text":"Season: add the cooled paste to the salted gat along with the spring onions and sesame seeds. Using clean hands, toss and massage everything together for 2 minutes so every leaf is coated. Taste a small piece: it should taste pleasantly salty now, but not salty enough to eat as is, the flavour will develop as it ferments."},{"text":"Pack: transfer the gat kimchi into a clean glass jar, pressing down so the vegetables are submerged under their own liquid. Leave a 5 cm gap at the top. If there isn't enough liquid to cover, sprinkle the remaining 1 tbsp salt over the top and leave for 10 minutes to release more brine."},{"text":"Ferment: seal the jar loosely (not airtight) and leave at cool room temperature or in the cold part of your kitchen for 3 days. After day 1, open the lid to let gas escape. By day 3, it will have a gentle fizz and a deep, funky flavour. Taste it, when it suits you, seal it tightly and refrigerate. It will keep for up to 3 weeks."}],"id":"bf5b0203-dde5-49d9-ac7d-b9ab27afc499"},{"steps":[{"text":"Make the marinade: whisk together pomegranate molasses, tamarind paste, oil, garlic, cumin, coriander, Aleppo pepper and salt in a small bowl."},{"text":"Prepare the fish: lay each fish on a cutting board and, using a sharp knife, cut down the spine from head to tail. Gently press the fish open so it lies flat like a butterfly, skin side down."},{"text":"Rub the marinade all over the fish, inside and out, making sure to coat the flesh well. Let sit for 10 minutes."},{"text":"Heat oil in a large heavy-based pan or cast iron frying pan over medium-high heat until shimmering. Carefully lay the fish skin side up in the pan."},{"text":"Cook for 6–7 minutes without moving, until the skin is golden and crispy. Gently flip and cook the other side for another 6–7 minutes until the flesh is opaque and cooked through (the flesh should flake easily when pressed with a fork)."},{"text":"Serve hot with lemon wedges and fresh parsley scattered over."}],"id":"9fe07c12-15da-4e36-bf65-92fa9458c70c"},{"notes":["Shave the burdock on a mandoline or with a vegetable peeler to keep the pieces thin and cook evenly.","You can make this with chicken thigh or thinly sliced pork instead of beef, same cooking time.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done."],"id":"15ba69dd-f173-4a55-a4b7-7752fd89426f"},{"steps":[{"text":"Bring a large pot of salted water to a boil. Add potatoes and cook until completely tender, about 15 minutes. Drain well in a colander."},{"text":"While potatoes cook, heat 2 tbsp oil in a large frying pan over medium-high heat. Add onions and cook, stirring occasionally, until they're golden and crispy, about 12 minutes. Season with salt and transfer to a paper towel."},{"text":"Mash warm potatoes with butter and milk until creamy but still with a little texture. Fold in most of the crispy onions and all the dill, reserving some onions for the top. Season generously with salt and pepper."},{"text":"Transfer to a serving bowl and top with reserved crispy onions. Eat immediately."}],"id":"debda2b4-0e6c-4103-a560-30f3d47188df"},{"notes":["Buy the pipis the day you cook and keep them on ice. Tap any open shells, they should close; if they don't, discard them.","You can make this with mussels or littleneck clams if you can't find pipis.","Food safety: Cook mussels, clams and pipis only if they are alive and tightly closed (or close when tapped), and discard any that stay shut after cooking."],"id":"39b5d68a-bd0a-43a4-b456-1a6ac844822a"},{"notes":["Pisua is a great make-ahead dish, prepare it and refrigerate for up to a day, then bake when needed (add 10 minutes to cooking time).","Leftovers keep in the fridge for 3 days and are even better reheated gently in a warm oven."],"id":"ff1c6f0c-b4f5-434c-898a-314df7cb9364"},{"notes":["This is even better made a day ahead. Cool, refrigerate overnight, then gently reheat. The flavours deepen and the fat is easy to lift off the cold surface.","Serve with crusty bread to soak up the sauce, and a simple green salad or steamed greens on the side.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"id":"10a5ecd6-d76d-477a-b08c-a7e5741bea8f"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;